def load_into(conn) -> None:
    """Insert every row above into an already-schema-initialized,
    empty connection. Foreign keys off for the duration of the load
    -- members and ambassadors reference each other, and this frozen
    snapshot's row order isn't guaranteed to satisfy that cycle
    incrementally, only once every row is in."""
    conn.execute('PRAGMA foreign_keys = OFF')
    for table in ['events', 'members', 'ambassadors', 'attendance', 'feedback', 'ambassador_social_posts', 'deletion_log']:
        spec = DEMO_SEED[table]
        placeholders = ', '.join('?' for _ in spec['columns'])
        columns_sql = ', '.join(spec['columns'])
        conn.executemany(
            f'INSERT INTO {table} ({columns_sql}) VALUES ({placeholders})',
            spec['rows'],
        )
    conn.commit()
    conn.execute('PRAGMA foreign_keys = ON')
